INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(52711, 'Psalms 136:1', 'Psalms', 136, 1, 'د څښتن شکر کوئ ځکه چې نېک دی هغه ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_1.mp3', '', 1761754199, 1761754199),
(52712, 'Psalms 136:2', 'Psalms', 136, 2, 'کوئ شکر د خدایانو د خدای ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_2.mp3', '', 1761754199, 1761754199),
(52713, 'Psalms 136:3', 'Psalms', 136, 3, 'شکر کوئ د څښتنانو د څښتن ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_3.mp3', '', 1761754199, 1761754199),
(52714, 'Psalms 136:4', 'Psalms', 136, 4, 'یوازې هغه دی چې لویې معجزې ښایي ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_4.mp3', '', 1761754199, 1761754199),
(52715, 'Psalms 136:5', 'Psalms', 136, 5, 'هغه پیدا کړي اسمانونه په خپل حکمت باندې ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_5.mp3', '', 1761754199, 1761754199),
(52716, 'Psalms 136:6', 'Psalms', 136, 6, 'خپره کړې یې ده ځمکه د اوبو دپاسه ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_6.mp3', '', 1761754199, 1761754199),
(52717, 'Psalms 136:7', 'Psalms', 136, 7, 'پیدا کړې هغه لویې رڼاګانې ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_7.mp3', '', 1761754199, 1761754199),
(52718, 'Psalms 136:8', 'Psalms', 136, 8, 'لمر چې حکومت کوي په ورځ باندې ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_8.mp3', '', 1761754199, 1761754199),
(52719, 'Psalms 136:9', 'Psalms', 136, 9, 'سپوږمۍ او ستوري چې حکومت کوي په شپې باندې ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_9.mp3', '', 1761754199, 1761754199),
(52720, 'Psalms 136:10', 'Psalms', 136, 10, 'لومړني زېږېدل شوي یې د مصریانو مړه کړل ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_10.mp3', '', 1761754199, 1761754199),
(52721, 'Psalms 136:11', 'Psalms', 136, 11, 'د اسراییلو قوم یې راوویست د مصر څخه ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_11.mp3', '', 1761754199, 1761754199),
(52722, 'Psalms 136:12', 'Psalms', 136, 12, 'په خپل قوي لاس او قدرتمندو مټو ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_12.mp3', '', 1761754199, 1761754199),
(52723, 'Psalms 136:13', 'Psalms', 136, 13, 'سره بحیره یې کړله بېله منځ کې ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_13.mp3', '', 1761754199, 1761754199),
(52724, 'Psalms 136:14', 'Psalms', 136, 14, 'د هغې له منځ نه یې خپل قوم تېر کړ ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_14.mp3', '', 1761754199, 1761754199),
(52725, 'Psalms 136:15', 'Psalms', 136, 15, 'خو فرعون او د هغه لښکر یې غرق کړل سره بحیره کې ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_15.mp3', '', 1761754199, 1761754199),
(52726, 'Psalms 136:16', 'Psalms', 136, 16, 'خپل خلک یې بوتلل د بیابان له لارې ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_16.mp3', '', 1761754199, 1761754199),
(52727, 'Psalms 136:17', 'Psalms', 136, 17, 'رانسکور کړل هغه لوی پاچاهان ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_17.mp3', '', 1761754199, 1761754199),
(52728, 'Psalms 136:18', 'Psalms', 136, 18, 'هغه مړه کړل قدرتمند پاچاهان ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_18.mp3', '', 1761754199, 1761754199),
(52729, 'Psalms 136:19', 'Psalms', 136, 19, 'هغه مړ کړلو سیحون د اموریانو پاچا ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_19.mp3', '', 1761754199, 1761754199),
(52730, 'Psalms 136:20', 'Psalms', 136, 20, 'مړ یې کړ عوج د باشان پاچا ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_20.mp3', '', 1761754199, 1761754199),
(52731, 'Psalms 136:21', 'Psalms', 136, 21, 'د هغوی هېوادونه یې خپل قوم ته په میراث کې ورکړل ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_21.mp3', '', 1761754199, 1761754199),
(52732, 'Psalms 136:22', 'Psalms', 136, 22, 'هغه یې ورکړل خپل خدمتګار اسراییل ته ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_22.mp3', '', 1761754199, 1761754199),
(52733, 'Psalms 136:23', 'Psalms', 136, 23, 'کله چې مونږ وخوړه ماتې هغه هېر نه کړلو ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_23.mp3', '', 1761754199, 1761754199),
(52734, 'Psalms 136:24', 'Psalms', 136, 24, 'مونږ یې له خپلو دښمنانو خلاص کړو ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_24.mp3', '', 1761754199, 1761754199),
(52735, 'Psalms 136:25', 'Psalms', 136, 25, 'هغه ورکوي رزق هر ژوندي مخلوق ته ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_25.mp3', '', 1761754199, 1761754199),
(52736, 'Psalms 136:26', 'Psalms', 136, 26, 'شکر وباسئ د اسمانونو خدای ته ده ابدي د هغه مینه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms136_verse_26.mp3', '', 1761754199, 1761754199),
(52737, 'Nahum 3:1', 'Nahum', 3, 1, 'افسوس په حال ستا ای خونړی ښاره چې یې ډک له دروغو او لوټ او تالان نه او هېڅ وخت بې قتلونو نه یې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_1.mp3', '', 1761754199, 1761754199),
(52738, 'Nahum 3:2', 'Nahum', 3, 2, 'غوږ ونیسئ: د قمچینې کړپهار ته، د ارابو شورماشور ته د اسونو تېزو منډو، د ګاډیو درزهار ته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_2.mp3', '', 1761754199, 1761754199),
(52739, 'Nahum 3:3', 'Nahum', 3, 3, 'اس سواران کوي حملې تورې پړقیږي او نېزې ځلیږي دي جوړې شوې ډېرۍ د مړو دي بې‌شمېره مړي عسکر ښوییږي په هغو باندې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_3.mp3', '', 1761754199, 1761754199),
(52740, 'Nahum 3:4', 'Nahum', 3, 4, 'ورکول کیږي سزا فاحشې نینوا ته هغې جذابې او وژونکې جادوګرې ته هغې وکړله جادو په قومونو باندې او غلامان یې کړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_4.mp3', '', 1761754199, 1761754199),
(52741, 'Nahum 3:5', 'Nahum', 3, 5, 'مطلق قادر څښتن وایي: نینوا زه یمه ستا په خلاف ستا نه به وباسم کالي زه به ښکاره کړمه قومونو ته ستا لوڅوالی او پاچاهیو ته به وشرموم تا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_5.mp3', '', 1761754199, 1761754199),
(52742, 'Nahum 3:6', 'Nahum', 3, 6, 'تا به پټه کړمه په چټلۍ کې زه به ګورمه په سپکه سترګه تاته او تا نه به جوړه تماشه کړمه زه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_6.mp3', '', 1761754199, 1761754199),
(52743, 'Nahum 3:7', 'Nahum', 3, 7, 'هرڅوک چې وویني تا نو تا نه به مخ اړوي هغوی به وایي چې ورانه شوې نینوا وبه کړي څوک ویر د هغې دپاره؟ څوک به ورکړي تسلي هغې ته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_7.mp3', '', 1761754199, 1761754199),
(52744, 'Nahum 3:8', 'Nahum', 3, 8, 'ای نینوا، ایا ته د مصر د پایتخت تیبس نه ښه یې؟ هغې هم یو سیند درلود چې د هغې ساتنه وکړي یعنې د نیل سیند د هغې دفاع کوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_8.mp3', '', 1761754199, 1761754199),
(52745, 'Nahum 3:9', 'Nahum', 3, 9, 'هغې په ایتوپیا او مصر باندې حکومت کاوه. د هغې د قدرت کوم حد نه ؤ. فوط او لیبیا د هغې ملګري وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_9.mp3', '', 1761754199, 1761754199),
(52746, 'Nahum 3:10', 'Nahum', 3, 10, 'خو بیاهم د تیبس خلک د اسیرانو په توګه په جلاوطنۍ بوتلل شول. د هرې کوڅې په سر کې د هغوی ماشومان وغورځول شول او ووژل شول. د هغوی مشران په زنځیرونو کې بوتلل شول او د دښمن عسکرو په خپل منځ کې د هغو د وېشلو دپاره پچه واچوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_10.mp3', '', 1761754199, 1761754199),
(52747, 'Nahum 3:11', 'Nahum', 3, 11, 'ای نینوا، ته به هم لکه د یو شرابي په شان نشه شې! ته به کوښښ کوې چې پټه شې او د دښمن څخه به پناه غواړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_11.mp3', '', 1761754199, 1761754199),
(52748, 'Nahum 3:12', 'Nahum', 3, 12, 'ستا ټولې کلاګانې به د پخو انځرو په شان وي. کله چې څوک دا ونې وخوځوي، نو مېوه به یې د هغه خولې ته ورولویږي!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_12.mp3', '', 1761754199, 1761754199),
(52749, 'Nahum 3:13', 'Nahum', 3, 13, 'ستا عسکر د ښځو په شان دي او ستا د وطن دروازې ستا د دښمنانو پرمخ خلاصې دي. اور به ستا د دروازو اړمونه وسوځوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_13.mp3', '', 1761754199, 1761754199),
(52750, 'Nahum 3:14', 'Nahum', 3, 14, 'د محاصرې دپاره تیاره شه او اوبه ذخیره کړه! خپلې جنګي کلاګانې قوي کړه! د خښتو د جوړولو دپاره خټه جوړه کړه او قالبونه تیار کړه!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_14.mp3', '', 1761754199, 1761754199),
(52751, 'Nahum 3:15', 'Nahum', 3, 15, 'ته چې هرڅه کوې، خو ته به په اور کې وسوځې او یا به په جنګ کې مړه شې. ته به داسې له منځه لاړه شې لکه څنګه چې ملخان فصلونه خوري. تاسو د ملخانو په شان زیات شوي یئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_15.mp3', '', 1761754199, 1761754199),
(52752, 'Nahum 3:16', 'Nahum', 3, 16, 'ستا د سوداګرانو شمېر د اسمان د ستورو نه زیات دی! خو اوس هغوی به داسې لاړ شي، لکه ملخان چې خپل وزرونه خپاره کړي او والوزي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_16.mp3', '', 1761754199, 1761754199),
(52753, 'Nahum 3:17', 'Nahum', 3, 17, 'ستا ساتونکي او مامورین د هغو ملخانو د سیل په شان دي چې په یخه ورځ په دېوالونو باندې ناست وي. خو کله چې لمر راښکاره شي، نو هغوی الوزي او هېڅوک نه پوهیږي چې هغوی چېرته لاړل!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_17.mp3', '', 1761754199, 1761754199),
(52754, 'Nahum 3:18', 'Nahum', 3, 18, 'ای د آشور امپراتوره، ستا حاکمان مړه شوي او ستا درانه خلک په ابدي خوب باندې ویده شوي دي! ستا خلک په غرونو باندې خواره واره شوي دي او هېڅوک نشته چې هغوی بېرته خپلو کورونو ته راولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_18.mp3', '', 1761754199, 1761754199),
(52755, 'Nahum 3:19', 'Nahum', 3, 19, 'ستا د زخمونو علاج نشته او ستا پرهارونه به جوړ نه شي. هرڅوک چې ستا د بربادۍ نه خبریږي، نو د خوشحالۍ نه خپل لاسونه پړقوي. ایا داسې څوک شته چې ستا د ظلم نه خلاص شوی وي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/nahum3_verse_19.mp3', '', 1761754199, 1761754199),
(52756, 'Exodus 40:1', 'Exodus', 40, 1, 'بیا څښتن موسی ته وویل:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_1.mp3', '', 1761754199, 1761754199),
(52757, 'Exodus 40:2', 'Exodus', 40, 2, '«د لومړۍ میاشتې په لومړۍ ورځ سپېڅلې خېمه ودروه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_2.mp3', '', 1761754199, 1761754199),
(52758, 'Exodus 40:3', 'Exodus', 40, 3, 'په هغې کې د لوظ صندوق چې لس حکمونه په کې دي، کېږده او هغه په پردې باندې پټ کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_3.mp3', '', 1761754199, 1761754199),
(52759, 'Exodus 40:4', 'Exodus', 40, 4, 'مېز دننه راوړه او سامان ورباندې کېږده. همدارنګه څراغدان هم دننه راوړه او څراغونه ورباندې کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_4.mp3', '', 1761754199, 1761754199),
(52760, 'Exodus 40:5', 'Exodus', 40, 5, 'د سرو زرو د خوشبویۍ د سوځولو د قربانۍ ځای د لوظ د صندوق په مخکې کېږده او د خېمې په دروازه باندې پرده ځوړنده کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_5.mp3', '', 1761754199, 1761754199),
(52761, 'Exodus 40:6', 'Exodus', 40, 6, 'د سوځېدونکې نذرانې د قربانۍ ځای د سپېڅلې خېمې د دروازې په مخکې کېږده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_6.mp3', '', 1761754199, 1761754199),
(52762, 'Exodus 40:7', 'Exodus', 40, 7, 'د خېمې او قربانۍ د ځای ترمنځ تشت کېږده او اوبه په کې واچوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_7.mp3', '', 1761754199, 1761754199),
(52763, 'Exodus 40:8', 'Exodus', 40, 8, 'د هغې ګردچاپېره یوه حوېلۍ جوړه کړه او د حوېلۍ په دروازه باندې پرده ځوړنده کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_8.mp3', '', 1761754199, 1761754199),
(52764, 'Exodus 40:9', 'Exodus', 40, 9, 'د مسح کولو تېل واخله او خېمه او هرڅه چې په کې دي هغه ورباندې مسح کړه. خېمه او د هغې ټول سامان وقف کړه او هغه به سپېڅلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_9.mp3', '', 1761754199, 1761754199),
(52765, 'Exodus 40:10', 'Exodus', 40, 10, 'بیا د سوځېدونکې نذرانې د قربانۍ ځای او د هغه ټول لوښي مسح کړه. د قربانۍ ځای وقف کړه او هغه به په پوره توګه سپېڅلی شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_10.mp3', '', 1761754199, 1761754199),
(52766, 'Exodus 40:11', 'Exodus', 40, 11, 'تشت او د هغه پایه مسح کړه او وقف یې کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_11.mp3', '', 1761754199, 1761754199),
(52767, 'Exodus 40:12', 'Exodus', 40, 12, 'هارون او د هغه زامن د سپېڅلې خېمې د دروازې خولې ته راوله او غسل ورته ورکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_12.mp3', '', 1761754199, 1761754199),
(52768, 'Exodus 40:13', 'Exodus', 40, 13, 'بیا هارون ته ځانګړي کالي ورواغونده او مسح او وقف یې کړه، ترڅو هغه د کاهن په توګه زما خدمت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_13.mp3', '', 1761754199, 1761754199),
(52769, 'Exodus 40:14', 'Exodus', 40, 14, 'د هغه زامن راوله او کمیسونه ورته ورواغونده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_14.mp3', '', 1761754199, 1761754199),
(52770, 'Exodus 40:15', 'Exodus', 40, 15, 'هغوی کټ مټ داسې مسح کړه لکه څنګه چې تا د هغوی پلار مسح کړ، ترڅو هغوی د کاهنانو په توګه زما خدمت وکړي. د هغوی مسح کېدل به د یو داسې کاهنتوب دپاره وي چې تل ترتله به دوام ومومي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_15.mp3', '', 1761754199, 1761754199),
(52771, 'Exodus 40:16', 'Exodus', 40, 16, 'موسی هرڅه کټ مټ د څښتن د حکم له مخې وکړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_16.mp3', '', 1761754199, 1761754199),
(52772, 'Exodus 40:17', 'Exodus', 40, 17, 'نو په دوهم کال وروسته له دې چې هغوی له مصر څخه لاړل، د اولې میاشتې په لومړۍ ورځ خېمه ودروله شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_17.mp3', '', 1761754199, 1761754199),
(52773, 'Exodus 40:18', 'Exodus', 40, 18, 'کله چې موسی خېمه ودروله، نو د هغې پایې یې په خپل ځای کې کېښودلې. چوکاټونه یې ودرول، اړمونه یې ورننه ویستل او ستنې یې ودرولې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_18.mp3', '', 1761754199, 1761754199),
(52774, 'Exodus 40:19', 'Exodus', 40, 19, 'لکه څنګه چې څښتن حکم کړی ؤ، هغه په خېمه باندې پوښ وغوړاوه او په هغه باندې یې باندینی پوښ واچاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_19.mp3', '', 1761754199, 1761754199),
(52775, 'Exodus 40:20', 'Exodus', 40, 20, 'هغه د تیږو دوه لوحې واخیستلې او د لوظ په صندوق کې یې کېښودلې. میلې یې د صندوق په کړۍ ګانو کې واچولې او هغه سرپوښ یې ورباندې کېښود چې کفاره ورباندې ادا کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_20.mp3', '', 1761754199, 1761754199),
(52776, 'Exodus 40:21', 'Exodus', 40, 21, 'لکه څنګه چې څښتن حکم کړی ؤ، موسی د لوظ صندوق خېمې ته دننه راوړ او پرده یې ځوړنده کړه. په دې ډول یې صندوق پټ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_21.mp3', '', 1761754199, 1761754199),
(52777, 'Exodus 40:22', 'Exodus', 40, 22, 'موسی مېز په خېمه کې شمال خواته د پردې څخه دباندې کېښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_22.mp3', '', 1761754199, 1761754199),
(52778, 'Exodus 40:23', 'Exodus', 40, 23, 'او لکه څنګه چې څښتن حکم کړی ؤ، په هغه باندې یې هغه سپېڅلې ډوډۍ کېښودله چې څښتن ته وړاندې کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_23.mp3', '', 1761754199, 1761754199),
(52779, 'Exodus 40:24', 'Exodus', 40, 24, 'څراغدان یې په خېمه کې مېز ته مخامخ جنوب خواته کېښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_24.mp3', '', 1761754199, 1761754199),
(52780, 'Exodus 40:25', 'Exodus', 40, 25, 'او لکه څنګه چې څښتن حکم کړی ؤ، د څښتن په حضور کې یې څراغونه کېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_25.mp3', '', 1761754199, 1761754199),
(52781, 'Exodus 40:26', 'Exodus', 40, 26, 'موسی د سرو زرو د قربانۍ ځای په خېمه کې د پردې په مخکې کېښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_26.mp3', '', 1761754199, 1761754199),
(52782, 'Exodus 40:27', 'Exodus', 40, 27, 'او لکه څنګه چې څښتن حکم کړی ؤ، په هغې باندې یې خوشبویي وسوځوله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_27.mp3', '', 1761754199, 1761754199),
(52783, 'Exodus 40:28', 'Exodus', 40, 28, 'بیا یې پرده د خېمې په دروازه کې ځوړنده کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_28.mp3', '', 1761754199, 1761754199),
(52784, 'Exodus 40:29', 'Exodus', 40, 29, 'لکه څنګه چې څښتن حکم کړی ؤ، هغه د سوځېدونکې نذرانې د قربانۍ ځای د خېمې دروازې ته نژدې ودروله او په هغې باندې یې سوځېدونکې او د غلې دانې نذرانې وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_29.mp3', '', 1761754199, 1761754199),
(52785, 'Exodus 40:30', 'Exodus', 40, 30, 'تشت یې د خېمې او د قربانۍ د ځای ترمنځ کېښود او د وینځلو دپاره یې اوبه په کې واچولې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_30.mp3', '', 1761754199, 1761754199),
(52786, 'Exodus 40:31', 'Exodus', 40, 31, 'او موسی، هارون او د هغه زامنو به د هغه څخه د خپلو لاسونو او پښو د وینځلو دپاره کار اخیست.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_31.mp3', '', 1761754199, 1761754199),
(52787, 'Exodus 40:32', 'Exodus', 40, 32, 'هرکله به چې هغوی خېمې ته ورننوتل، یا به د قربانۍ ځای ته ورتلل، نو خپل لاسونه او پښې به یې وینځلې، لکه څنګه چې څښتن موسی ته حکم کړی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_32.mp3', '', 1761754199, 1761754199),
(52788, 'Exodus 40:33', 'Exodus', 40, 33, 'بیا موسی د خېمې او د قربانۍ د ځای ګردچاپېره حوېلۍ جوړه کړه او د حوېلۍ په دروازې باندې یې پرده ځوړنده کړه. نو موسی کار پای ته ورساوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_33.mp3', '', 1761754199, 1761754199),
(52789, 'Exodus 40:34', 'Exodus', 40, 34, 'بیا ورېځ خېمه پټه کړه او د څښتن د جلال څخه ډکه شوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_34.mp3', '', 1761754199, 1761754199),
(52790, 'Exodus 40:35', 'Exodus', 40, 35, 'نو له دې امله موسی نه شو کولای چې خېمې ته ورننوځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_35.mp3', '', 1761754199, 1761754199),
(52791, 'Exodus 40:36', 'Exodus', 40, 36, 'اسراییلیانو به یوازې هغه وخت خپل کمپ بل ځای ته انتقالاوه چې کله به ورېځ د خېمې څخه پورته کېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_36.mp3', '', 1761754199, 1761754199),
(52792, 'Exodus 40:37', 'Exodus', 40, 37, 'ترڅو پورې چې ورېځ به هلته ولاړه وه، نو هغوی به خپل کمپ نه انتقالاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_37.mp3', '', 1761754199, 1761754199),
(52793, 'Exodus 40:38', 'Exodus', 40, 38, 'د ټولو سفرونو په دوران کې ټولو اسراییلیانو د ورځې له خوا د څښتن د حضور ورېځ د خېمې دپاسه لیدلی شوه او د شپې له خوا به یې لیدل چې په ورېځ کې اور بلیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus40_verse_38.mp3', '', 1761754199, 1761754199),
(52794, 'Psalms 49:1', 'Psalms', 49, 1, 'واورئ دا ټولو خلکو د نړۍ ټولو اوسېدونکو غوږ شئ!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_1.mp3', '', 1761754199, 1761754199),
(52795, 'Psalms 49:2', 'Psalms', 49, 2, 'ای غټانو او کوچنیانو ای شتمنو هم خوارانو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_2.mp3', '', 1761754199, 1761754199),
(52796, 'Psalms 49:3', 'Psalms', 49, 3, 'زه به کومه د حکمت خبرې خلکو ته پوهه ورکوي د زړه بیان زما', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_3.mp3', '', 1761754199, 1761754199),
(52797, 'Psalms 49:4', 'Psalms', 49, 4, 'زه به خپل فکر اړومه متلونو لره حلوم به معماګانې د رباب په اواز', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_4.mp3', '', 1761754199, 1761754199),
(52798, 'Psalms 49:5', 'Psalms', 49, 5, 'ولې به وېرېږم د خطر په وخت کله چې زه شمه راګېر د شریرانو له خوا', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_5.mp3', '', 1761754199, 1761754199),
(52799, 'Psalms 49:6', 'Psalms', 49, 6, 'د داسې خلکو له خوا څوک چې کړي توکل په دولت او وهي لافې د ډېر زیات ثروت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_6.mp3', '', 1761754199, 1761754199),
(52800, 'Psalms 49:7', 'Psalms', 49, 7, 'هېڅوک نه شي کولای کړي ادا د چا د سر بیه هېڅوک خدای ته کفاره د چا د ژوند نه شي سپارلی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_7.mp3', '', 1761754199, 1761754199),
(52801, 'Psalms 49:8', 'Psalms', 49, 8, 'ځکه ډېره قیمتي ده د انسان د ژوندون بیه څه چې څوک ادا کوي هغه هېڅکله کافي نه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_8.mp3', '', 1761754199, 1761754199),
(52802, 'Psalms 49:9', 'Psalms', 49, 9, 'چې څوک وساتي له مرګه چې ژوندی وي تل ترتله', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_9.mp3', '', 1761754199, 1761754199),
(52803, 'Psalms 49:10', 'Psalms', 49, 10, 'هرڅوک ویني چې هوښیار خلک هم مړه کیږي همدارنګه ساده‌ګان او بې‌عقلان هم بیا نورو ته پرېږدي هغوی خپل دولت', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_10.mp3', '', 1761754199, 1761754199),
(52804, 'Psalms 49:11', 'Psalms', 49, 11, 'تل ترتله د هغوی قبرونه دي د دوی کورونه هلته اوسیږي به دوی ټولو نسلونو پورې که څه هم دوی یو وخت په خپل نامه لرلې ځمکې', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_11.mp3', '', 1761754199, 1761754199),
(52805, 'Psalms 49:12', 'Psalms', 49, 12, 'د انسان شان او شوکت نه شي خلاصولی دی له مرګه څاروي چې مري هغه به هم مړ کیږي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_12.mp3', '', 1761754199, 1761754199),
(52806, 'Psalms 49:13', 'Psalms', 49, 13, 'دا دی د هغو سرنوشت چې توکل کړي په خپل ځان او د هغو د پیروانو چې باور کړي په بیان د دوی', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_13.mp3', '', 1761754199, 1761754199),
(52807, 'Psalms 49:14', 'Psalms', 49, 14, 'هغوی به مړه شي لکه چې مري پسونه مرګی به وي د دوی شپون نېکان به کړي په دوی حکومت سبا ته خپلو کورونو څخه لېرې په قبرونو کې به خوسا شي زر د هغو خلکو مړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_14.mp3', '', 1761754199, 1761754199),
(52808, 'Psalms 49:15', 'Psalms', 49, 15, 'خو خدای به ما لره خلاصون راکوي هغه به کش کړي ما د مرګ له پنجو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_15.mp3', '', 1761754199, 1761754199),
(52809, 'Psalms 49:16', 'Psalms', 49, 16, 'ته مه ډارېږه که یو څوک شي شتمن د کور د هغه چې جلال زیات شي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_16.mp3', '', 1761754199, 1761754199),
(52810, 'Psalms 49:17', 'Psalms', 49, 17, 'کله چې مړ شي هغه نه شي وړی له ځانه سره ده سره لاړ به نه شي قبر ته جلال د هغه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms49_verse_17.mp3', '', 1761754199, 1761754199);